    ALL_CATS.map((c) => h('option', { value: c, selected: c === catFilter }, c)));

  const listWrap = h('div');
  const totalsLine = h('p', { class: 'filtered-total' });

  function filtered() {
    const q = search.value.trim().toLowerCase();
