        h('td', { class: `num amount ${t.type}` }, `${t.type === 'expense' ? '−' : '+'}${money(t.amountCents)}`),
        h('td', { class: 'num', style: 'white-space:nowrap;width:64px' },
          iconBtn('pencil', 'Edit', () => openTxForm(t)),
          iconBtn('trash', 'Delete', async () => {
