.budget-tip svg { width: 17px; height: 17px; flex: none; color: var(--amber); margin-top: 1px; }

/* ---------- bills ---------- */
.billrow .billname { font-weight: 600; font-size: 14.5px; }
.billrow .billmeta { font-size: 12.5px; color: var(--ink-3); }
.due-pill {
  font-size: 11.5px; font-weight: 700; border-radius: 999px; padding: 3px 9px; white-space: nowrap;
}
.due-pill.soon { background: var(--amber-lt); color: var(--amber); }
.due-pill.today { background: var(--red-lt); color: var(--red); }
.due-pill.later { background: var(--paper-2); color: var(--ink-2); }
.due-pill.paid { background: var(--ok-lt); color: var(--ok); }
.due-pill.overdue { background: var(--red); color: #fff; }

/* ---------- goals ---------- */
.goalcard { display: flex; flex-direction: column; gap: 9px; }
.goalcard .g-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }
.goalcard .g-name { font-family: var(--serif); font-size: 17px; font-weight: 600; }
.goalcard .g-pct { font-family: var(--serif); font-size: 22px; font-weight: 650; color: var(--teal); }
.goalcard .g-nums { font-size: 13px; color: var(--ink-2); font-variant-numeric: tabular-nums; }
.goalcard .g-eta { font-size: 12px; color: var(--ink-3); }
.goalcard .g-actions { display: flex; gap: 7px; align-items: center; margin-top: 3px; }
.goalcard .g-actions input {
  width: 88px; border: 1px solid var(--line); border-radius: 8px; padding: 6px 9px; font-size: 13.5px;
}

/* ---------- reports ---------- */
.rep-card h3 { font-size: 15.5px; margin-bottom: 3px; }
.rep-card .rep-sub { font-size: 12.5px; color: var(--ink-3); margin-bottom: 12px; }
.catbar-row { display: grid; grid-template-columns: 132px 1fr 74px; gap: 10px; align-items: center; padding: 5px 0; font-size: 13.5px; }
.catbar-row .cb-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.catbar-row .cb-amt { text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; }
.payee-row { display: flex; justify-content: space-between; gap: 10px; padding: 7px 0; border-bottom: 1px solid var(--line-2); font-size: 14px; }
.payee-row:last-child { border-bottom: 0; }
.payee-row .py-amt { font-variant-numeric: tabular-nums; font-weight: 600; }
.payee-row .py-ct { color: var(--ink-3); font-size: 12px; }
.chart-note { font-size: 12px; color: var(--ink-3); margin-top: 8px; }
.chart-legend { display: flex; gap: 16px; flex-wrap: wrap; margin-top: 10px; font-size: 12.5px; color: var(--ink-2); }
.chart-legend .cl { display: inline-flex; align-items: center; gap: 6px; }
.chart-legend .sw { width: 11px; height: 11px; border-radius: 3px; }

/* svg chart text */
svg text { font-family: var(--sans); }
.chart-axis { font-size: 10.5px; fill: var(--ink-3); }
